36	/**
37	 * Rejects a create/update owner request whose email address uses a disposable domain
38	 * (mailinator.com, tempmail.com, guerrillamail.com), responding 400 Bad Request. The
39	 * domain is matched case-insensitively; an absent email is left untouched.
40	 */
41	@ControllerAdvice
42	@Order(Ordered.HIGHEST_PRECEDENCE)
43	public class OwnerDisposableEmailAdvice implements RequestBodyAdvice {
44	
45	    private static final Set<String> DISPOSABLE_DOMAINS =
46	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
47	
48	    @Override
49	    public boolean supports(MethodParameter methodParameter, Type targetType,
50	                            Class<? extends HttpMessageConverter<?>> converterType) {
51	        return OwnerFieldsDto.class.equals(targetType);
52	    }
53	
54	    @Override
55	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
56	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
57	        if (isDisposable(((OwnerFieldsDto) body).getEmail())) {
58	            throw new DisposableEmailException();
59	        }
60	        return body;
61	    }
62	
63	    private boolean isDisposable(String email) {
64	        if (email == null) {
65	            return false;
66	        }
67	        int at = email.lastIndexOf('@');
68	        return at >= 0 && DISPOSABLE_DOMAINS.contains(email.substring(at + 1).toLowerCase(Locale.ROOT));
69	    }
70	
71	    @Override
72	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
73	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
74	        return body;
75	    }
76	
77	    @Override
78	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
79	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
80	        return inputMessage;
81	    }
82	
83	    @ExceptionHandler(DisposableEmailException.class)
84	    @ResponseBody
85	    public ResponseEntity<Void> handleDisposableEmail(DisposableEmailException e) {
86	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).build();
87	    }
88	
89	    /** Signals that the email address uses a disposable domain. */
90	    static class DisposableEmailException extends RuntimeException {
91	    }
92	}
