19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
31	    @Mapping(target = "locality",
32	        expression = "java(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode()))")
33	    @Mapping(target = "timezone",
34	        expression = "java(org.springframework.samples.petclinic.util.Localities.timezoneFor(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode())))")
35	    @Mapping(target = "contactPreference",
36	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
37	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
38	    @Mapping(target = "checkDigit",
39	        expression = "java(org.springframework.samples.petclinic.util.CheckDigits.luhn(owner.getCustomerCode()))")
40	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
41	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
42	    @Mapping(target = "telephoneDisplay",
43	        expression = "java(org.springframework.samples.petclinic.util.TelephoneFormatter.toDisplay(owner.getTelephone()))")
44	    @Mapping(target = "selfLink",
45	        expression = "java(owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
46	    OwnerDto toOwnerDto(Owner owner);
47	
48	    /** Age band derived from birthDate against registrationDate: MINOR (under 18), ADULT (18-64) or SENIOR (65+); null when birthDate is absent. */
49	    default String ageBand(Owner owner) {
50	        java.time.LocalDate birthDate = owner.getBirthDate();
51	        if (birthDate == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        int age = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
55	        if (age < 18) {
56	            return "MINOR";
57	        }
58	        return age < 65 ? "ADULT" : "SENIOR";
59	    }
60	
61	    /** The single duplicate-detection key: normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty). */
62	    default String identityKey(Owner owner) {
63	        return orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + orEmpty(owner.getHouseholdId());
64	    }
