13	
14		@Test
15		void coreIdentityKeyIsSha256Hex() throws Exception {
16			JsonNode r = fetchOwner(createOwnerOk(structuredOwner()));
17			String key = r.get("identityKey").asText();
18			assertTrue(key.matches("[0-9a-f]{64}"), key);
19		}
