 * @author Michael Isvy
 */
@Entity
@Table(name = "owners")
public class Owner extends Person {
    @Column(name = "address")
    @NotEmpty
    private String address;

    @Column(name = "city")
    @NotEmpty
    private String city;

    @Column(name = "telephone")
    @NotEmpty
    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be valid E.164")
    private String telephone;

    @Column(name = "email")
    private String email;

    @Column(name = "postcode")
    private String postcode;

    @Column(name = "registration_date", columnDefinition = "DATE")
    private java.time.LocalDate registrationDate;

    @Column(name = "birth_date", columnDefinition = "DATE")
    private java.time.LocalDate birthDate;

    public java.time.LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(java.time.LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    @Column(name = "customer_code")
    private String customerCode;

    @Column(name = "household_id")
    private String householdId;

    @Column(name = "namesake_count")
    private Integer namesakeCount;

    @Column(name = "household_member_count")
    private Integer householdMemberCount;

    @Column(name = "membership_level")
    private Integer membershipLevel;

    public Integer getMembershipLevel() {
        return this.membershipLevel;
    }

    @Column(name = "possible_duplicate_of")
    private Integer possibleDuplicateOf;

    @Column(name = "deleted")
    private boolean deleted;

    public boolean isDeleted() {
        return this.deleted;
    }

    public void setDeleted(boolean deleted) {
        this.deleted = deleted;
    }

    public Integer getPossibleDuplicateOf() {
        return this.possibleDuplicateOf;
    }

    /** Record the id of an existing owner this one is a possible (soft) duplicate of, or null. */
    public void assignPossibleDuplicate(Collection<Owner> existingOwners) {
        this.possibleDuplicateOf = org.springframework.samples.petclinic.util.PossibleDuplicates.matchIn(this, existingOwners);
    }

    public String getCustomerCode() {
        return this.customerCode;
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    /** Record how many of {@code existingOwners} share this owner's first and last name, case-insensitively. */
    public void assignNamesakeCount(Collection<Owner> existingOwners) {
        int count = 0;
        for (Owner other : existingOwners) {
            if (getFirstName().equalsIgnoreCase(other.getFirstName())
                && getLastName().equalsIgnoreCase(other.getLastName())) {
                count++;
            }
        }
        this.namesakeCount = count;
        assignHouseholdMemberCount(existingOwners);
        this.membershipLevel = org.springframework.samples.petclinic.util.MembershipLevels.cap(this, existingOwners);
    }

    public Integer getHouseholdMemberCount() {
        return this.householdMemberCount;
    }

    /** Record how many owners (this one included) share this owner's household after this create. */
    public void assignHouseholdMemberCount(Collection<Owner> existingOwners) {
        int count = 1;
        for (Owner other : existingOwners) {
            if (householdId != null && householdId.equals(other.getHouseholdId())) {
                count++;
            }
        }
        this.householdMemberCount = count;
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    /** Assign the '<REGION>-<HASH8>' customer code: region from the postcode, HASH8 from telephone+lastName. */
    public void assignCustomerCode(Collection<Owner> existingOwners) {
        this.customerCode = CustomerCodes.buildUnique(getCity(), getPostcode(), getTelephone(), getLastName(), existingOwners);
    }

    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
    private Set<Pet> pets;

    public java.time.LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(java.time.LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

